INSERT INTO `projects` (`id`, `company_id`, `nombre_proyecto`, `descripcion_proyecto`, `category_id`, `fecha_inicio`, `fecha_finalizacion`, `ubicacion_pais`, `ubicacion_estado`, `ubicacion_ciudad`, `cliente_contratante`, `area_superficie`, `servicios_productos`, `galeria_imagenes`, `video_url`, `estado`, `estado_moderacion`, `vistas`, `consultas`, `created_at`, `updated_at`) VALUES (3, 269, ' Parque Las Carmelitas', '<p><span style="color: rgb(255, 255, 255)"><strong>El 26 de octubre de 2024, como cierre del Congreso Parques 2024, llevamos a cabo la Construcción Comunitaria del Parque Las Carmelitas en Mérida, Yucatán.  Gracias al apoyo de Fundación FEMSA y JIMUMEX logramos reconstruir este parque en tan solo 6 horas, trabajando codo a codo con la comunidad para transformar un espacio público en un lugar de encuentro, recreación y convivencia. </strong></span><strong><br></strong></p>', NULL, NULL, NULL, NULL, 'Yucatán', 'Mérida', NULL, NULL, '["FEMSA ","JIMUMEX "]', '["/uploads/images/7f608d16-b8d4-4991-a06d-5d7bca4c8584_1763278925745.jpg"]', 'https://www.youtube.com/watch?v=BVrsT427j-M', 'publicado', 'pendiente', 0, 0, '2025-11-16 07:42:06', '2025-11-16 07:42:06');
